            '**一句话分工**：**生成模型学联合分布 P(X,Y)**（或 P(X|Y)P(Y)），要"理解数据怎么来的"，再经贝叶斯定理得后验（朴素贝叶斯、GMM、HMM、扩散/LM 都是广义生成式）；**判别模型直接学 P(Y|X) 或判别函数**（逻辑回归、SVM、神经网络）——只关心"给定 X 怎么分"，不浪费算力建模 X 本身的分布（清华原题判断："贝叶斯分类器是生成式、逻辑回归是判别式"为**对**）。',
            '**优劣对照（高频追问）**：生成式——需要更多数据/更强的分布假设（估错分布全错），但**能生成样本、能检出低概率异常、能用无标注数据**；判别式——直接优化决策边界、通常精度更高特征工程更自由，但**不知道"正常长什么样"**（无法判异常、无法生成）。工程选型：分类精度优先用判别式；异常检测/小样本/有生成需求考虑生成式。AI Checklist 还列了第三条路：**判别函数不建模任何概率**（直接输出分界面，SVM 原始形态）。',
            '**MAP 与 MLE 的关系（清华原题）**：MAP = 最大化 log 似然 + **log 先验**；**先验均匀时 MAP = MLE**。朴素贝叶斯分类就是"MAP 决策"的实例（选后验最大的类）；MAP 是贝叶斯学派对频率学派 MLE 的修正——用先验表达"数据不够时的常识"。',
            '**正则化 = 高斯/拉普拉斯先验（MAP 视角，必考联动）**：**L2 正则 ≈ 高斯先验**（惩罚大权重，平滑）、**L1 ≈ 拉普拉斯先验**（稀疏解）——正则化不是启发式，是"把对参数的先验信念写进目标函数"。这一视角把过拟合题（L1/L2）与贝叶斯估计串成一条线。',
