            '**两个世界的真实差异**：**低代码平台（Dify/Coze/n8n）**——可视化拖拽工作流、内置 RAG/知识库/模型管理/发布渠道（Coze 直接发到飞书/微信），**原型速度极快、非工程师可用**；天花板也明确：复杂状态流转（循环、条件回跳、人工介入后恢复）、自定义记忆策略、精细的上下文工程在画布上会变成"面条图"，调试（断点、单步、日志）弱于 IDE。**代码框架（LangGraph/AutoGen/AgentScope）**——Agent 表达为**状态图/状态机**（节点是步骤、边是转移、状态显式管理），循环与分支是一等公民、可任意接私有组件与测试——控制力换开发门槛。',
            '**选型的第一判据：谁在用它做什么**。业务/运营同学配置**流程确定的知识问答与工单流**（DAG 就够）→ 平台；工程师做**产品级 Agent**（状态复杂、要评估与回归、要接公司内部系统）→ 代码框架；混合团队常见路径：**平台做 PoC 验证价值 → 证明可行后用代码重写核心链路**（或反过来：代码做核心、平台做外围运营配置）——"什么时候该拖拽、什么时候该写代码"是面试官想听的真实判断。',
            '**不管选哪边，通用的工程要点（显水平的部分）**：**Prompt 与配置版本化**（工作流导出 YAML 入库、平台自带版本管理也要导出备份——否则"谁改了线上提示词"没法追溯）；**评测先行**（改一版跑基准，与 Agent evals 题衔接——低代码平台最容易"感觉挺好就上了"）；**成本与观测**（每步的 token 消耗、各节点的成功率——平台的日志要能导出到自有监控）；**私有化考量**（Dify 开源可私有化部署、Coze 有国内版但数据边界要评估）。',
            '**对「框架还是裸写」的追问预备**：Agent 核心循环（工具调用 + 状态管理）几百行就能写，**轻场景裸写更干净**（少一层抽象、调试直接）；框架的价值在**状态持久化（checkpoint 恢复）、人工介入（interrupt）、并发编排**这些造起来费劲的轮子；面试的成熟答案不是站队，是"**按需要的状态复杂度与团队画像选，并知道所选方案的逃生通道**"（平台锁定：工作流定义能否导出迁移；框架锁定：抽象是否过重）。与多智能体题分工：那题讲编排模式，本题讲工具栈选型。',
