            '**Function Calling 流程**（要能逐步说清）：① 应用在请求里**声明工具清单**（名称、功能描述、JSON Schema 参数）；② 模型判断需要时**不输出自然语言**，而是输出**结构化的函数调用请求**（函数名 + 参数）；③ **执行方是你的应用代码**，真正去调 API/查数据库；④ 把结果作为 tool 消息回传，模型基于结果继续生成。关键认知：**模型从不执行任何东西，它只“点菜”，上菜的是你的代码**——这也是权限控制的边界所在。',
            '工具设计的质量决定 Agent 上限：**描述写得清楚**（什么时候该用、参数含义、反例）比模型聪明更管用；参数 schema 尽量扁平；工具数量多时做检索或分组，避免选择困难。',
            '**MCP（Model Context Protocol）**是工具接入的标准化协议：把“工具/资源/提示”以标准 server 形式暴露，任何支持 MCP 的客户端都能复用——解决每个应用各写一套工具适配的碎片化问题。',
