            '**BPE 训练流程**：① 语料先拆成最细的字符序列（加特殊结束符）；② 统计**相邻字符对的出现频次**；③ 把**最高频的一对合并**成新符号加入词表；④ 语料重写，重复②③直到词表达到目标大小。**编码（推理时）**：按学到的合并规则优先级把新文本贪心合并成子词——这就是 GPT 系列的字节级 BPE（BBPE），任何字节序列都能编码（emoji、乱码也不怕）。',
