            '**长期记忆的关键设计不是"存"而是"管"**：**写入策略**（什么值得记——显式让模型调用 save_memory 工具，比"全量落库再检索"噪音小得多）；**检索策略**（按任务相关性检索 + 时间衰减 + 重要度加权，Generative Agents 的经典配方）；**遗忘与冲突**（过时记忆要降权/覆盖，"用户换了部门"要能改而不是叠加）；**记忆的可解释性**（能列出"我记住了你什么"并可删除——合规刚需）。上下文快满时的**压缩策略**（历史摘要而不是截断，保留决策链丢弃过程）是另一道必考子题。',
            '**MCP（Model Context Protocol）解决的是集成碎片化**：MCP 之前，每个应用（IDE/聊天客户端/Agent 框架）对接每个工具（数据库/GitHub/内部 API）都要写一份 glue code，M×N 的集成爆炸。MCP 把它标准化成 **M×N 变 M+N**：工具方实现一次 **MCP Server**（暴露 tools/resources/prompts 三类能力），任意支持 MCP 的宿主（MCP Client）即插即用——本质是"**AI 应用的 USB-C 接口**"，类比 LSP 之于编辑器。能说出 tools（模型可调用的动作）/resources（可读取的上下文）/prompts（可复用的模板）三类原语，说明真了解协议。',
