            '**去模糊的成像模型**：G = F⊗H + N（观测 = 真实图卷模糊核 + 噪声）；频域里卷积变乘法，**逆滤波 = 频域相除**——但模糊核 H 是低通的，高频处 H→0，相除把噪声放大到爆；**Wiener 滤波**加 K/scale 项抑制：H 大处接近逆滤波、H 小处保守衰减——"信噪比加权的最优线性恢复"。',
            '**病态性（ill-posed）**：多组不同的 F 与 N 能给出相同的 MSE——单靠观测无法唯一确定解，必须加**先验**：自然图像分段平滑、梯度稀疏 → 加 L1 正则 ‖∇F‖₁（保留强边缘的同时压噪声振铃）；**盲去卷积**（核未知）再加核先验（H 非负且稀疏）交替估计——正则化 = 把病态问题变成"带偏好的良态问题"，与 ML 的正则化是同一哲学。',
