            '余弦的经典坑（必考细节）：只看方向不看强度——用户 A 评两部电影 1 分和 2 分、用户 B 评 4 分和 5 分，余弦相似度高达 **0.98**，但 A 明显不喜欢；换成**调整余弦（对用户相似度，把每个评分减去该影片的均分）是 -1**（A 在两部片上都低于均分、B 都高于均分——口味相反），与直觉相符。注意皮尔逊（减各自评分均值）这里仍得 +1——它修的是相对走向，修不掉绝对强度。皮尔逊本质就是中心化后的余弦，但布尔向量没有"高低起伏的变化趋势"，所以皮尔逊不适合布尔。',
            '**UserCF vs ItemCF 的取舍**：UserCF 三问题——用户量大算力瓶颈、口味变化快相似度过期、用户间共同行为稀疏且集中在热门物；ItemCF 反转计算对象后三点全解——物品数通常少于用户数、物品相似度比人口味**静态**（可充分离线化）、物品的消费者远多于用户共同行为（稀疏度更好）。对应两种产品形态：TopN"猜你喜欢"（离线算好存缓存）与详情页"看了又看/买了又买"（实时查相似列表）。',
            '改进三板斧与工程规模感：**热门惩罚**（热门物体现的是被煽动不是兴趣，UserCF 要对热门降权）、**时间衰减**（指数负幂——"小时候喜欢的东西不代表现在的口味"）、**中心化**（去铁杆粉丝的非理性打分与个人宽严标准）；外加 **Slope One**——不算相似度、直接算物品间"平均评分差距"并用共同评分人数做置信加权，对余弦的小样本教训天然免疫。两两相似度是 O(N²) 大坑——稀疏存储、**DIMSUM 采样**（Twitter 提出、Spark 已实现，低维采样近似全维结果）、点积只算共同用户、相似列表只留 top-K。（来源：推荐系统三十六式 07/08/09、手把手搭建推荐系统 19）',
