            '推荐系统有**两个不同的去重需求**，别混为一谈：①**内容源去重**——抓取/聚合场景下海量相似文章（过滤对象是内容本身）；②**已推荐去重**——推过的不再推（过滤对象是物品 ID）。前者难在"相似"的判定，后者难在海量 ID 的存储。',
            '**MD5 指纹只治绝对重复**：改一个字指纹全变，无法容忍轻度改写。**Simhash 的流程**：分词带权重 → 每词哈希成 64 位整数、0/1 映成 -1/1 → 乘词权重 → 逐位累加 → 按符号位输出 64 位指纹；判重 = 指纹**汉明距离 ≤ 3**。精髓：**低权重词的 ±1 翻不动累加和的符号**——删掉"了""的"不影响指纹，天然容忍轻度改写（Google 公开的网页去重经典方案，信息流产品直接继承）。',
            '**Bloomfilter 管第二类**：位数组 + n 个独立哈希函数，"一定不存在"的判断零误漏、只有小概率误判（误判 = 某条内容永远不再推给该用户，可承受）；推荐场景按"用户 + 物品 ID"维度建。机制细节（不能删除 → 计数布隆/布谷鸟）是缓存穿透题的内容——本题的亮点是**主动区分"一个算法服务两个去重场景"的分工**。',
            '**加权采样**（召回多样性的便宜工具）：给每个带权重 w 的样本算分数 **Sᵢ = R^(1/wᵢ)**（R 为 0~1 随机数），取分数 top-k——被采概率正比权重（k=1 时严格成立）；等价视角：取 **Eᵢ = −ln(R)/wᵢ**（以 wᵢ 为率、均值 1/wᵢ 的指数分布随机数），**Eᵢ 最小的 k 个**即加权采样结果。用途：用户标签太多时按权采样参与召回（降复杂度 + 每次略有变化）、榜单展示加微扰防千篇一律。',
            '**蓄水池采样**（流式版）：总量未知的数据流取 k 条，第 i 个元素以 **k/i** 概率替换池中随机一条——任意时刻每条被选概率恒为 k/n；加权版把 Sᵢ 与池中最小分比较。收束一句：负采样（Word2Vec/MF/YouTubeDNN）本质也是采样——**采样是推荐系统贯穿数据、召回、训练、展示四层的通用技术**，而不只是算法小技巧。（来源：推荐系统三十六式 22/23）',
