            '隐因子的物理意义：k 维空间每一维没有名字、不可解释，故称**隐因子**；用户向量 = 在若干因素上的偏好，物品向量 = 物品被关注的因素，推荐分数 = 两向量点积。训练就是标准机器学习两板斧：**损失函数（预测误差平方，控偏差）+ L2 正则（参数平方和，控方差防过拟合）**。',
            '**SVD 家族演进谱系（背这条线）**：基础 SVD → **BiasSVD**（r̂ = μ + bᵢ + bᵤ + p·qᵀ：全局平均分 + 物品偏置 + 用户偏置——影评站均 3 分、《肖申克》高 1 分、你习惯压 0.5 分，光靠三项就能猜 3.5）→ **SVD++**（用户做过行为的物品各带一个隐向量求和 ∑xᵢ，用户属性同理 ∑y——显式评分少的大多数人靠隐式反馈和属性兜底）→ **timeSVD**（评分按时间加权/分时间区间学隐向量/节日单独训练）——**每一代都是往目标函数里加一类真实世界因素**。',
