            '**One-Class 难题**：把"用户会不会做某事"当二分类，可收集到的只有正类（用户干了），"明确不干"的数据不存在。把所有缺失值当 0 负样本有两个矛盾——"没反馈"可能是**不知道物品存在**而不是不喜欢；正负极度不平衡，且"矩阵分解的初心就是填充这些缺失值，全填 0 等于忘记初心"。',
