            '**MAB 建模三要素**：臂（可以是物品、**推荐策略**、类目三个抽象层级——"先 Bandit 选策略再在策略内选物品"是工程常用两级结构）、回报（是否点击）、环境（用户）；评价用**累积遗憾 regret**（每次选择与最优选择的收益差之和），模拟对比看哪个算法遗憾增长慢。',
            '三算法对比：**ε-greedy**（ε 概率随机探索、1−ε 选当前最优——简单但探索无差别，对"没试过"和"试过很差"一视同仁）；**UCB**（评分 = 平均收益 + Bonus，Bonus 本质是置信区间宽度——被选次数少则 Bonus 大，**乐观地给不确定者机会**）；**汤普森采样**（每臂挂 Beta(a,b) 分布，a=点击数、b=未点击数，每轮各采一个随机数取最大——a+b 大则分布窄趋近真实收益，a+b 小则分布宽有机会爆出大随机数，**探索与利用在采样里自动权衡**，一行代码可实现）。模拟效果排序：完全随机 < 朴素贪心 < ε-greedy < UCB ≈ Thompson。',
            '**LinUCB**（Yahoo 2010，上下文 Bandit）：裸 Bandit 不用特征，新物品只能从零积累数据；LinUCB 用用户/物品/场景特征经**岭回归**（样本数少于特征数时的正则解）估每臂的期望收益与置信上界——鹿晗粉丝对两个鹿晗广告的反馈可以泛化到新鹿晗广告，**新内容不必从零探索**；特征恒为 1 时退化为普通 UCB。代价：候选臂只能几百个以内（每臂都要算置信区间）。',
            '落地与骨感：新用户注册后**以类目/Topic 为臂**跑汤普森采样推 TopN、按点击更新 a/b——几次交互就能画出兴趣分布，比"热门榜糊脸"快得多。但现实很少有公司严格用理性方案做探索——产品生命周期短没动力、探索收益长期才显现、试错伤当期指标；落地三原则：**探索的物品保质量**（不感兴趣也不招反感）、**探索位置靠产品设计**（让用户有耐心陪你玩）、进阶方向是 COFIBA 类"协同过滤 + Bandit"（用户聚类集体决策 + 反馈后动态重新聚类）。（来源：推荐系统三十六式 02/16/17/18、手把手搭建推荐系统 26）',
