            '**实时推荐的三层定义**（很多人嘴里的"实时"只是第二层）：①**给得及时**——服务实时响应，是底线，做到不算实时推荐；②**用得及时**——**特征**实时更新：刚买的东西立刻进用户历史、参与下一次召回，只影响当前用户；③**改得及时**——**模型**实时更新：新行为让相关物品对的共现数 +1、相似度矩阵全局变化，影响所有用户的推荐。三层的难度、意义、效果完全不同。',
            '架构骨架：行为事件 → **Kafka**（topic/partition/offset，消费者可从任意 offset 重放——批流共读同一份日志的基础）→ 流计算平台（Storm 的 spout/bolt/topology；Spark Streaming 实为小批量；Flink 高吞吐低延迟）→ 清洗入库 + 增量计算 → 更新线上推荐库；同时日志落 HDFS 供离线全量重算——**实时结果与离线批量互为补充，即 Lambda 架构**。',
            '**i2i 相似度的增量更新**（第三层的具体化）：sim(i,j) 分子 = 共同评分用户数、分母 = 两物品各自用户数的平方根之积；收到一条评分事件 → 取出该用户历史物品列表 → 逐对更新共现计数与物品计数 → 重算涉及的物品对相似度 → 再更新受影响的推荐结果；Storm 实现即几个 Bolt 的分工（发射物品对、更新分子、更新分母、刷新结果）。',
            '**近线层（Nearline）的定位**（Netflix 定义背熟）："**用实时数据，不保证实时服务**"——消费最新行为做两件事：把用户刚反馈过的物品从离线推荐结果中剔除 + 用小批量梯度下降更新模型参数；与在线请求**异步**，不阻塞响应。三层架构口诀：**离线**（不用实时数据/不提供实时服务）、**近线**（用实时数据/不保证实时服务）、**在线**（用实时数据/保证实时服务）。',
            '**突发流量的效率四招**：**剪枝**（相似度是 [0,1] 的有界随机变量，用 **Hoeffding 不等式 ε = √(ln(1/δ)/2n)** 算出"更新 n 次后即可信任均值"——达到次数就停止更新，均值低于阈值直接斩掉该物品对）；**加窗**（只保留最近 K 次会话/K 条行为——兴趣会衰减，旧行为本该降权）；**采样**（热门物品/活跃用户的突发数据流采样）；**合并**（上游把多条事件聚合后再触发更新）。再加缓存三板斧（活跃用户历史、热门物品特征与相似列表，Redis/Memcached——代价是一致性难保证）。（来源：推荐系统三十六式 25/28、手把手搭建推荐系统 02/28）',
