            '攻击的数学本质：CF 是群体投票，攻击 = **操纵选民**——UserCF 的选民是"相似用户"，ItemCF 的选民是"相似物品"。',
            '**托攻击（Shilling Attack）标准配方**：批量注册假用户 → 模仿目标人群的历史行为（对目标用户喜欢的物品打同样高分，混进他的最近邻）→ 给扶持物品打高分/打压物品打低分 → **陪跑物品**上打掩护分避免暴露。三类物品构成靶子：**目标物品**（靶心）/ **助攻物品**（造相似度）/ **陪跑物品**（掩人耳目）；按陪跑层打分方式分**随机攻击**（以全局均值为心的正态随机）与**平均分攻击**（逐物品打均值）。',
            '进阶打法：**热门攻击**——假用户同时给畅销书和目标书打高分，i2i 就会把目标书算成畅销书的相似物品，在爆款页面的"买了又买"里搭便车（某电商图书的真实案例；粉丝出征、集体维权也会无意间形成同样效果）；**分段攻击**——圈定一个人群，给"该人群的最爱集合 + 目标物品"同时打分，实现定向投放/定向消失。',
            '**防护三层**：平台级（提高批量注册成本——验证码；教育用户给真实反馈，数据真实比例是根本）；数据级（标注假用户训练分类器实时拦截；无监督聚类揪出"目标性太强、分布异常"的假用户群体，整群删除）；算法级（**UserCF 更脆弱**：限制低质量/新用户投票权、加重相似度平滑因子压掉异常高值、多算法融合互为冗余）。反直觉细节：**ItemCF 被攻击更容易被人工发现**——《小时代》与《肖申克的救赎》高度相似这种反直觉结果上线前就会被识破，UserCF 的攻击藏在"给你推荐的人"里用户毫无感知——这就是"基于用户的协同过滤更常被攻击"的原因。（来源：推荐系统三十六式 21/32）',
